
.reveal-line {
  opacity: 0.25;

  transition: opacity 0.6s ease, transform 0.6s ease;
}

.reveal-line.in-view {
  opacity: 1;

}

.vibelab-logo {
  height: 1.5rem;
}


.circle-bg {
  -webkit-background-size: cover;
  -moz-background-size: cover;
  -o-background-size: cover;
  background-size: cover;
  background-attachment: cover;
  position: absolute;
  right: -22%;
  left: inherit;
  top: 0;
  bottom: 0;
  margin: auto;
  height: 110vw;
  width: 110vw;
  filter: brightness(0.7);
  z-index: 0;
}

@media (min-width: 768px) {


  .circle-bg {
    position: absolute;
    right: -70%;
    top: 0;
    left: inherit;
    bottom: 0;
    margin: auto;
    height: 90vw;
    width: 90vw;
    border-radius: 50%;
    filter: brightness(1);
    z-index: 0;
  }
}


.circle-shape {
  position: absolute;
  top: 0;
  left: 15vw;
  bottom: 0;
  margin: auto;
  height: 70vw;
  width: 70vw;
  border-radius: 50%;
  z-index: 0;
  animation: flash 3s infinite linear;
}

@media (min-width: 768px) {
  .circle-shape {
    position: absolute;
    right: -30%;
    top: 0;
    left: auto;
    bottom: 0;
    margin: auto;
    height: 60vw;
    width: 60vw;
    border-radius: 50%;
    z-index: 0;
    animation: flash 4s infinite linear;
  }


}

@keyframes flash {
  0% {
    border: solid 1px transparent;
  }

  12% {
    border: solid 1px transparent;
  }

  15% {
    border: solid 1px rgb(114, 127, 75);
  }

  30% {
    border: solid 1px rgba(114, 127, 75, 0.116);
  }

  48% {
    border: solid 1px rgba(114, 127, 75, 0);
  }

  75% {
    border: solid 1px transparent;
  }

  100% {
    border: solid 1px transparent;
  }
}



